List<String> topo(Map<String, List<String>> g) {
  final done = <String>{};
  final post = <String>[];
  void visit(String v) {
    if (!done.add(v)) return;
    for (final w in g[v]!) {
      visit(w);
    }
    post.add(v);
  }

  g.keys.forEach(visit);
  return post.reversed.toList();
}

void main() {
  print(topo({'a': ['b'], 'b': ['c'], 'c': []}));
}
