  final inDeg = {for (final v in g.keys) v: 0};
  for (final ts in g.values) {
    for (final t in ts) {
      inDeg[t] = inDeg[t]! + 1;
    }
  }
  var cur = [for (final v in g.keys) if (inDeg[v] == 0) v];
  final res = <List<String>>[];
  while (cur.isNotEmpty) {
    res.add(cur);
    final next = <String>[];
    for (final v in cur) {
      for (final w in g[v]!) {
        if ((inDeg[w] = inDeg[w]! - 1) == 0) next.add(w);
      }
    }
    cur = next;
  }
  return res;
}

