bool valid(Map<String, List<String>> g, List<String> order) {
  final pos = {for (final (i, v) in order.indexed) v: i};
  for (final MapEntry(key: u, value: ts) in g.entries) {
    for (final v in ts) {
      if (pos[u]! > pos[v]!) return false;
    }
  }
  return true;
}

